    ENV_SRC = `/* Where a key is read, asked at run time first: a Cloudflare Worker's own
   bindings (where a secret set on Cloudflare always arrives \u2014 process.env has
   it only with nodejs_compat on), then the process environment (Node,
   Vercel, Netlify), and Astro's import.meta.env last \u2014 .env under astro dev,
   and in a build whatever the building machine had, frozen into this file. */
let bindings: Record<string, unknown> = {};
async function loadBindings(): Promise<void> {
  const agent = (globalThis as unknown as { navigator?: { userAgent?: string } }).navigator?.userAgent;
  if (agent !== 'Cloudflare-Workers') return;
  /* A variable, as with nodemailer: the module exists only on Cloudflare,
     and a bare specifier would not typecheck anywhere else. */
  const pkg = 'cloudflare:workers';
  const mod = await import(/* @vite-ignore */ pkg).catch(() => null) as { env?: Record<string, unknown> } | null;
  bindings = mod?.env ?? {};
}
const env = (name: string): string => {
  const bound = bindings[name];
  const proc = (globalThis as unknown as { process?: { env?: Record<string, string> } }).process?.env ?? {};
  const meta = (import.meta as unknown as { env?: Record<string, string> }).env ?? {};
  return String((typeof bound === 'string' ? bound : undefined) ?? proc[name] ?? meta[name] ?? '');
};`;
